SELECT AVG(resale_price) AS average_resale_price 
FROM resale 
WHERE flat_type = '5 ROOM' AND town = 'ANG MO KIO' AND strftime('%Y', month) = '2020';

SELECT AVG(resale_price) AS average_resale_price 
FROM resale 
WHERE flat_type = '3 ROOM' AND town = 'JURONG WEST' AND strftime('%Y', month) = '2024';

SELECT AVG(resale_price) AS average_resale_price 
FROM resale 
WHERE town = 'PUNGGOL' AND flat_type = 'EXECUTIVE' AND strftime('%Y', month) = '2023';

SELECT AVG(resale_price) AS average_resale_price 
