SELECT COUNT(*) 
FROM resale
WHERE flat_type = '4 ROOM' AND strftime('%Y', month) = '2019';

SELECT MEDIAN(resale_price) AS median_resale_price
FROM resale
WHERE flat_type = '4 ROOM' AND town = 'CHOA CHU KANG' AND strftime('%Y', month) = '2017';

SELECT AVG(resale_price / floor_area_sqm) AS average_price_per_sqm
FROM resale
WHERE flat_type = '3 ROOM' AND town = 'ANG MO KIO' AND strftime('%Y', month) = '2018';

SELECT AVG(resale_price / floor_area_sqm) AS avg_price_per_sqm
FROM resale
WHERE town = 'ANG MO KIO' AND flat_type = '3 ROOM' AND strftime('%Y', month) = '2018';

SELECT AVG(resale_price / floor_area_sqm) AS average_price_per_sqm
FROM resale
WHERE flat_type = '5 ROOM' AND town = 'ANG MO KIO' AND strftime('%Y', month) = '2019';

SELECT AVG(resale_price / floor_area_sqm) AS avg_price_per_sqm
FROM resale
WHERE town = 'ANG MO KIO' AND flat_type = '5 ROOM' AND strftime('%Y', month) = '2019';

SELECT AVG(resale_price / floor_area_sqm) AS average_price_per_sqm 
FROM resale 
WHERE flat_type = '3 ROOM' AND town = 'CENTRAL AREA' AND strftime('%Y', month) = '2019';

SELECT AVG(resale_price / floor_area_sqm) AS avg_price_per_sqm
FROM resale
WHERE flat_type = '3 ROOM' AND town = 'CENTRAL AREA' AND month LIKE '2019%';

SELECT AVG(resale_price / floor_area_sqm) AS average_price_per_sq_metre 
FROM resale 
WHERE town = 'HOUGANG' AND flat_type = 'EXECUTIVE' AND strftime('%Y', month) = '2017';

SELECT AVG(resale_price * 1.0 / floor_area_sqm) AS avg_price_per_sqm
FROM resale
WHERE town = 'HOUGANG' AND flat_type = 'EXECUTIVE' AND strftime('%Y', month) = '2017';

SELECT AVG(resale_price / floor_area_sqm) AS avg_price_per_sqm
FROM resale
WHERE flat_type = '5 ROOM' AND town = 'PUNGGOL' AND strftime('%Y', month) = '2017';

SELECT AVG(resale_price / floor_area_sqm) AS average_price_per_sqm 
FROM resale 
WHERE town = 'TAMPINES' AND flat_type = '3 ROOM' AND strftime('%Y', month) = '2024';

SELECT COUNT(DISTINCT street_name) 
FROM resale 
WHERE resale_price > 1000000 AND strftime('%Y', month) = '2024';

SELECT AVG(resale_price / floor_area_sqm) 
FROM resale 
WHERE town = 'BISHAN' AND flat_type IN ('3 ROOM', '4 ROOM') AND strftime('%Y', month) = '2022';

SELECT COUNT(*) AS total_multigeneration_flats_sold
FROM resale
WHERE flat_model IN ('MULTI-GENERATION', 'MULTI GENERATION', 'MULTI GENERATION APARTMENT', 'MULTI-GENERATION APARTMENT');

SELECT COUNT(*) AS total_1_room_flats_sold
FROM resale
WHERE flat_type = '1 ROOM';

SELECT ROUND(AVG(CASE WHEN month LIKE '2024%' THEN resale_price END) - AVG(CASE WHEN month LIKE '2019%' THEN resale_price END), 2) AS price_difference
FROM resale
WHERE town = 'BEDOK' AND flat_type = '4 ROOM';

SELECT COUNT(DISTINCT town) FROM (
    SELECT town, AVG(resale_price / floor_area_sqm) AS avg_price_per_sqm
    FROM resale
    WHERE flat_type = '4 ROOM' AND strftime('%Y', month) = '2024'
    GROUP BY town
) WHERE avg_price_per_sqm > 6500;
